// Package postgres is the operations module's Repo on the platform database (queries.sql, generated by sqlc).
package postgres

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"time"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/operations"
)

// Repo implements operations.Repo.
type Repo struct {
	q *Queries
}

var _ operations.Repo = (*Repo)(nil)

// NewRepo uses the open database db.
func NewRepo(db *sql.DB) *Repo { return &Repo{q: New(db)} }

// Create stores a new operation.
func (r *Repo) Create(ctx context.Context, op operations.Operation) error {
	return r.q.InsertOperation(ctx, InsertOperationParams{ID: op.ID, UserID: op.UserID, Kind: op.Kind,
		Subject: op.Subject, Status: string(op.Status), CreatedAt: op.CreatedAt})
}

// Finish records a finished operation.
func (r *Repo) Finish(ctx context.Context, op operations.Operation) error {
	p := FinishOperationParams{Status: string(op.Status), ID: op.ID}
	if op.Result != nil {
		p.Result = op.Result
	}
	if op.Error != nil {
		p.Error = sql.NullString{String: *op.Error, Valid: true}
	}
	if op.FinishedAt != nil {
		p.FinishedAt = sql.NullTime{Time: *op.FinishedAt, Valid: true}
	}
	return r.q.FinishOperation(ctx, p)
}

// Get reads an operation, or operations.ErrNotFound.
func (r *Repo) Get(ctx context.Context, id string) (operations.Operation, error) {
	row, err := r.q.GetOperation(ctx, id)
	if errors.Is(err, sql.ErrNoRows) {
		return operations.Operation{}, operations.ErrNotFound
	}
	if err != nil {
		return operations.Operation{}, err
	}
	op := operations.Operation{ID: row.ID, UserID: row.UserID, Kind: row.Kind, Subject: row.Subject,
		Status: operations.Status(row.Status)}
	if row.Result != nil {
		op.Result = json.RawMessage(row.Result)
	}
	if row.Error.Valid {
		op.Error = &row.Error.String
	}
	op.CreatedAt = row.CreatedAt
	if row.FinishedAt.Valid {
		op.FinishedAt = &row.FinishedAt.Time
	}
	return op, nil
}

// FailRunning marks every running operation failed with reason.
func (r *Repo) FailRunning(ctx context.Context, reason string, at time.Time) (int64, error) {
	return r.q.FailRunning(ctx, FailRunningParams{Error: sql.NullString{String: reason, Valid: true},
		FinishedAt: sql.NullTime{Time: at, Valid: true}})
}
